+fn crossings(a: Point2, b: Point2, l: &[Point2], ts: &mut Vec<f64>) {
+    let (minx, maxx) = (a.x.min(b.x), a.x.max(b.x));
+    let (miny, maxy) = (a.y.min(b.y), a.y.max(b.y));
